<?php

declare(strict_types=1);namespace ProjectPress\Tests\Unit;use PHPUnit\Framework\TestCase;use ProjectPress\Includes\Core\Schema;use ProjectPress\Includes\Core\WP\Database;use ProjectPress\Includes\Project\Delivery\Deployment;use ProjectPress\Includes\Project\Delivery\Environment;use ProjectPress\Includes\Project\Delivery\Release;use ProjectPress\Includes\Project\Delivery\Sprint;final class PhaseNineDeliveryTest extends TestCase{public function testDeliveryTablesAreRegistered():void{Schema::register_tables();$tables=Database::get_core_tables();foreach(array('sprints','releases','deployments','environments')as$table)$this->assertArrayHasKey($table,$tables);}public function testDeliveryModelsRemainProjectScoped():void{foreach(array(new Sprint(array('project_id'=>18)),new Release(array('project_id'=>18)),new Deployment(array('project_id'=>18)),new Environment(array('project_id'=>18)))as$model)$this->assertSame(18,$model->get_project_id());}}
